/* Adaptive compositor only. Existing studies own feed/media/discussion fixture behavior. */
(function(){
'use strict';
const E=id=>document.getElementById(id),params=new URLSearchParams(location.search),model=window.RelaxeAdaptiveState.create(),frame=E('adaptive-feed'),reader=E('adaptive-reader'),host=E('adaptive-window');
let readerAppearance=false,feedOverlay=false,reportedColumns=null,feedReady=false,readerReady=false,readerMounted=false,appearance='light',palette='blue',feedFamily='compact',lastReaderConfig='',lastFeedConfig='';
const send=(target,data)=>target.contentWindow?.postMessage(data,location.origin);
function note(text){E('adaptive-status').textContent=text}
function current(){return model.snapshot()}
function status(){const s=current(),l=s.effective;note(l.reason+'. Preferred feed columns: '+s.preferredColumns+'; renderer reports: '+(reportedColumns??'waiting')+'. Fixture post opens: '+s.opens+'. Resize opens no post.')}
function syncFeed(){if(!feedReady)return;const s=current(),values={'layout-kind':s.family,'layout-columns':String(s.preferredColumns),'nav-theme':palette,'nav-mode':appearance,'nav-text':String(s.text)};const key=JSON.stringify(values);if(key!==lastFeedConfig){send(frame,{type:'relaxe-layout-comparison',values});lastFeedConfig=key}}
function syncReader(){if(!readerReady)return;const s=current();if(!s.selected)return;const values={post:s.selected,appearance,palette,text:String(s.text),account:params.get('account')==='guest'?'guest':'weekendreader'};const key=JSON.stringify(values);if(key!==lastReaderConfig){send(reader,{type:'relaxe-adaptive-reader-config',values});lastReaderConfig=key}}
function paint(){const focusedFrame=document.activeElement,s=current(),l=s.effective;host.dataset.rail=String(l.rail);host.dataset.split=String(l.split);host.dataset.media=String(s.media);host.dataset.ime=String(s.ime>0);host.style.width=s.width+'px';host.style.height=s.height+'px';host.style.setProperty('--scale',s.text);host.style.setProperty('--rail-width',l.navWidth+'px');host.style.setProperty('--feed-width',l.feedWidth+'px');host.style.setProperty('--ime-height',s.ime+'px');for(const [key,value]of Object.entries(window.RelaxeStudyTheme.tokens(window.RelaxeStudyTheme.directions[0],{foundation:'selected',appearance,palette,text:String(s.text)})))host.style.setProperty(key,value);E('adaptive-context').textContent='Home · Best · '+(params.get('account')==='guest'?'Guest example':'signed-in example');E('adaptive-window').querySelector('.adaptive-content').style.paddingInlineEnd=s.hinge+'px';E('adaptive-feed-pane').hidden=!l.feedVisible;E('adaptive-reader-pane').hidden=!l.readerVisible;E('adaptive-keyboard').hidden=s.ime===0;if(!l.feedVisible&&focusedFrame===frame){if(readerReady){reader.focus();send(reader,{type:'relaxe-adaptive-reader-focus'})}else E('adaptive-reader-heading').focus({preventScroll:true})}if(!l.readerVisible&&focusedFrame===reader)frame.focus();status();syncFeed();syncReader();if(readerReady&&!l.readerVisible)send(reader,{type:'relaxe-adaptive-reader-suspend'})}
function openReader(id){if(readerAppearance)return;model.open(id);const s=current();if(!s.selected)return;if(!readerMounted){readerMounted=true;reader.src='details.html?adaptive-reader=1&post='+encodeURIComponent(s.selected)+'&rev=143'}paint();E('adaptive-reader-heading').textContent='Post and comments';E('adaptive-reader-heading').focus({preventScroll:true})}
function closeReader(){if(readerAppearance){send(reader,{type:'relaxe-adaptive-reader-back'});return}const id=current().selected;model.close();paint();send(frame,{type:'relaxe-adaptive-focus',post:id})}
function back(){const s=current();if(feedOverlay){send(frame,{type:'relaxe-adaptive-media-back'});return}if(s.effective.readerVisible&&readerReady)send(reader,{type:'relaxe-adaptive-reader-back'});else if(s.media)send(frame,{type:'relaxe-adaptive-media-back'});else note('Existing parent navigation route. No native screen was opened.')}
E('adaptive-nav').innerHTML=window.RelaxeShell.markup();for(const b of E('adaptive-nav').querySelectorAll('button'))b.addEventListener('click',()=>{if(b.dataset.destination==='home')closeReader();else{suspend();E('adaptive-dialog-text').textContent='Existing '+b.dataset.destination+' route for this account. This study changes window composition only; no destination or preference is changed.';E('adaptive-dialog').showModal()}});E('adaptive-nav').querySelector('[data-destination="home"]').setAttribute('aria-current','page');
function suspend(){send(frame,{type:'relaxe-adaptive-suspend'});if(readerReady)send(reader,{type:'relaxe-adaptive-reader-suspend'})}
document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend()});E('adaptive-menu').addEventListener('click',()=>{suspend();E('adaptive-dialog-text').textContent='The accepted drawer, account switcher and subscriptions remain in their existing routes. A rail does not replace those choices or force a permanently open drawer.';E('adaptive-dialog').showModal()});E('adaptive-dialog-close').addEventListener('click',()=>E('adaptive-dialog').close());E('adaptive-back').addEventListener('click',back);
for(const id of ['adaptive-size','adaptive-text','adaptive-appearance','adaptive-palette','adaptive-family','adaptive-ime','adaptive-hinge'])E(id).addEventListener('change',()=>{const [width,height]=E('adaptive-size').value.split('x').map(Number);appearance=E('adaptive-appearance').value;palette=E('adaptive-palette').value;model.configure({width,height,text:+E('adaptive-text').value,ime:+E('adaptive-ime').value,hinge:+E('adaptive-hinge').value,family:E('adaptive-family').value});paint()});
window.addEventListener('message',event=>{if(event.origin!==location.origin)return;const type=event.data?.type;
 if(event.source===frame.contentWindow){if(type==='relaxe-compact-ready'){feedReady=true;lastFeedConfig='';send(frame,{type:'relaxe-adaptive-bind'});syncFeed()}if(type==='relaxe-adaptive-open'&&['p1','p2','p3','p4','p5'].includes(event.data.post))openReader(event.data.post);if(type==='relaxe-layout-capacity'&&Number.isInteger(event.data.effective)&&event.data.effective>=1&&event.data.effective<=6){reportedColumns=event.data.effective;status()}if(type==='relaxe-adaptive-feed-overlay'&&typeof event.data.active==='boolean')feedOverlay=event.data.active;if(type==='relaxe-adaptive-media'&&typeof event.data.active==='boolean'){model.configure({media:event.data.active,mediaReader:false});paint()}return}
 if(event.source===reader.contentWindow){if(type==='relaxe-adaptive-reader-appearance'){readerAppearance=event.data.open===true;E('adaptive-feed-pane').inert=readerAppearance;E('adaptive-nav').inert=readerAppearance;E('adaptive-menu').disabled=readerAppearance;}if(type==='relaxe-adaptive-reader-ready'){readerReady=true;lastReaderConfig='';syncReader()}if(type==='relaxe-adaptive-reader-close')closeReader()}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!E('adaptive-dialog').open&&!['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName)){event.preventDefault();back()}});
for(const [param,id]of [['window','adaptive-size'],['text','adaptive-text'],['appearance','adaptive-appearance'],['palette','adaptive-palette'],['family','adaptive-family']]){const value=params.get(param);if(value&&[...E(id).options].some(o=>o.value===value))E(id).value=value}if(params.get('focus')==='1')document.body.classList.add('adaptive-focus');const [width,height]=E('adaptive-size').value.split('x').map(Number);appearance=E('adaptive-appearance').value;palette=E('adaptive-palette').value;feedFamily=E('adaptive-family').value;model.configure({width,height,text:+E('adaptive-text').value,family:feedFamily});paint();
frame.src='navigation.html?study=17&layout='+feedFamily+'&layout-embedded=1&settings-feed=1&adaptive-study=1&account='+(params.get('account')==='guest'?'guest':'weekendreader')+'&rev=143';
})();
